WITH t AS (SELECT l.loan_id,l.amount,a.district_id FROM loan l JOIN account a USING(account_id) WHERE l.duration=24 AND a.frequency='POPLATEK TYDNE' ORDER BY l.amount DESC,l.loan_id LIMIT 10),
d AS (SELECT DISTINCT d.district_id,CAST(d.A4 AS INTEGER) inh,d.A11 sal FROM district d JOIN t USING(district_id))
SELECT (SELECT district_id FROM d ORDER BY inh DESC,district_id LIMIT 1) AS district_id,(SELECT inh FROM d ORDER BY inh DESC,district_id LIMIT 1) AS inhabitants,(SELECT ROUND(AVG(sal),2) FROM d) AS avg_salary;
